// PREP INPUT — normaliza o corpo do webhook vindo da app.
// Contrato de entrada (POST /webhook/cav-inbound):
// { comercial_id, texto? , audio_base64? , audio_mime? ,
//   evento_pendente_id? , evento_pendente? {dominante,transcricao_original,eventos} , resposta? }
const body = $input.first().json.body || $input.first().json || {};

const comercial_id = (body.comercial_id || '').trim();
const texto        = (body.texto || '').trim();
const audio_base64 = body.audio_base64 || '';
const audio_mime   = body.audio_mime || 'audio/webm';

if (!comercial_id) throw new Error('comercial_id em falta — a app tem de identificar o comercial.');
const resposta = body.resposta || '';
if (!texto && !audio_base64 && !resposta) throw new Error('Sem conteudo: envia "texto", "audio_base64" ou "resposta".');

// Ref legivel e unica do evento: EVT-AAAAMMDD-HHMMSS-XXX
const d = new Date();
const p = n => String(n).padStart(2, '0');
const ref = 'EVT-' + d.getUTCFullYear() + p(d.getUTCMonth() + 1) + p(d.getUTCDate())
          + '-' + p(d.getUTCHours()) + p(d.getUTCMinutes()) + p(d.getUTCSeconds())
          + '-' + Math.random().toString(36).slice(2, 5).toUpperCase();

return [{
  json: {
    modo: audio_base64 ? 'audio' : 'texto',
    tem_audio: !!audio_base64,
    comercial_id,
    texto: texto || resposta,
    audio_base64,
    audio_mime,
    evento_pendente_id: body.evento_pendente_id || null,
    evento_pendente: body.evento_pendente || null,
    resposta: resposta || null,
    ref,
    recebido_em: d.toISOString(),
  }
}];

// TRANSCRICAO (AUDIO) — le a resposta da chamada isolada 'Transcrever Audio (Gemini)'
// (sem CANDIDATOS/VENDEDOR no contexto, para nao dar ao modelo nada por onde inventar).
const raw = $input.first().json || {};
let texto = '';
try { texto = (raw.candidates[0].content.parts || []).map(p => p.text || '').join(''); } catch (e) {}
texto = texto.trim();
const semFala = !texto || texto === '(sem fala percetível)';
const prep = $('Prep Input').first().json;
return [{ json: { ...prep, transcricao: semFala ? '' : texto, sem_fala: semFala, origem_transcricao: 'gemini' } }];

// TRANSCRICAO (TEXTO) — a app ja transcreveu no browser; passa a limpo.
const prep = $('Prep Input').first().json;
const texto = (prep.texto || '').trim();
if (!texto) throw new Error('Texto vazio.');
const { audio_base64, ...limpo } = prep;
return [{ json: { ...limpo, transcricao: texto, origem_transcricao: 'app' } }];

// MONTAR PAYLOAD — constroi o bloco dinamico que a Secretaria recebe (contrato §2 v2.12).
// Entradas: Transcricao (audio|texto), Get Comercial, Get CANDIDATOS, Get CONFIG.

const prep = $('Prep Input').first().json;
const transNodeName = prep.tem_audio ? 'Transcrição (áudio)' : 'Transcrição (texto)';
let transVal = '';
try { transVal = ($(transNodeName).first().json.transcricao || '').trim(); } catch (e) {}
const base = { ...prep, transcricao: transVal };
const trans = base.transcricao || '';

// ---- comercial -------------------------------------------------------------
let comercial = {};
try { comercial = $('Get Comercial').first().json || {}; } catch (e) {}
const cf = comercial.fields || {};
const VENDEDOR = cf.Nome || cf.nome || 'Desconhecido';

// ---- sequencia de estagios (universal §3.6.1) -------------------------------
const SEQ_UNIVERSAL = ['lead','aguarda_documentos','aguarda_decisao_banco','aprovado',
                       'proposta_enviada','aguarda_banco','escritura_marcada','fecho'];

// ---- CONFIG ----------------------------------------------------------------
// Cada linha da tabela CONFIG e um par chave/valor; o valor pode ser JSON.
let cfgRows = [];
try { cfgRows = ($('Get CONFIG').first().json.records) || []; } catch (e) {}
const cfg = {};
for (const r of cfgRows) {
  const f = r.fields || {};
  const k = f.chave || f.Chave || f.key || f.Nome || f.nome;
  const v = f.valor !== undefined ? f.valor : (f.Valor !== undefined ? f.Valor : f.value);
  if (!k) continue;
  let parsed = v;
  if (typeof v === 'string') { try { parsed = JSON.parse(v); } catch (e) { parsed = v; } }
  cfg[String(k).trim().toLowerCase()] = parsed;
}
const seqCfg = cfg['sequencia_estagios'] || cfg['sequencia'] || null;
const SEQUENCIA_ESTAGIOS = { ordem: (seqCfg && seqCfg.ordem) || (Array.isArray(seqCfg) ? seqCfg : SEQ_UNIVERSAL) };
const ETAPAS_OBRIGATORIAS = cfg['etapas_obrigatorias'] || [];
const MOTIVOS_SAIDA       = cfg['motivos_saida'] || null;
const FLAGS_AUTO          = cfg['flags_auto'] || [];

// ---- candidatos (leads ativas do comercial) --------------------------------
let leadRecs = [];
try { leadRecs = ($('Get CANDIDATOS').first().json.records) || []; } catch (e) {}
const hoje = new Date();
const diasDesde = iso => {
  if (!iso) return null;
  const d = new Date(iso); if (isNaN(d)) return null;
  return Math.floor((hoje - d) / 86400000);
};
// so as leads deste comercial (o nome do campo de ligacao varia; aceitar variantes)
const doComercial = r => {
  const f = r.fields || {};
  const v = f.Comercial || f.Comerciais || f.comercial || null;
  const ids = Array.isArray(v) ? v : (v ? [v] : []);
  return !ids.length || ids.includes(base.comercial_id);
};
const CANDIDATOS = leadRecs.filter(doComercial).map(r => {
  const f = r.fields || {};
  const fase = f.estagio || f.Estagio || f['Estágio'] || 'lead';
  const idx  = SEQUENCIA_ESTAGIOS.ordem.indexOf(fase);
  const cand = {
    id: r.id,
    nome: f.Nome || f.nome || '',
    alcunhas: f.alcunhas ? String(f.alcunhas).split(',').map(s => s.trim()).filter(Boolean) : [],
    telefone: f.Telefone || f.telefone || null,
    fase_atual: fase,
    tipo: f.tipo || 'aquisicao',
    ultima_nota: f.ultima_nota || null,
  };
  if (idx >= 0) cand.indice_fase = idx;
  const dd = diasDesde(f.ultimo_contacto || f.Data_ultimo_contacto || null);
  if (dd !== null) cand.dias_desde_ultimo_contacto = dd;
  if (fase === 'aguarda_documentos' && f.checklist_documentos) {
    try {
      cand.checklist_documentos = typeof f.checklist_documentos === 'string'
        ? JSON.parse(f.checklist_documentos) : f.checklist_documentos;
    } catch (e) {}
  }
  if (fase === 'aguarda_decisao_banco' && f.propostas_banco) {
    try {
      cand.propostas_banco = typeof f.propostas_banco === 'string'
        ? JSON.parse(f.propostas_banco) : f.propostas_banco;
    } catch (e) {}
  }
  return cand;
});

// ---- calendarios (resolver datas por consulta, nunca por calculo) ----------
const DIAS = ['domingo','segunda-feira','terca-feira','quarta-feira','quinta-feira','sexta-feira','sabado'];
const MESES = ['janeiro','fevereiro','marco','abril','maio','junho','julho','agosto','setembro','outubro','novembro','dezembro'];
const iso = d => d.toISOString().slice(0, 10);

const CALENDARIO = [];
for (let i = 0; i <= 30; i++) {
  const d = new Date(hoje.getTime() + i * 86400000);
  CALENDARIO.push({ data: iso(d), dia_semana: DIAS[d.getDay()], offset_dias: i });
}
const CALENDARIO_MESES = [];
for (let m = 0; m < 12; m++) {
  const d = new Date(hoje.getFullYear(), hoje.getMonth() + m, 1);
  CALENDARIO_MESES.push({ mes: MESES[d.getMonth()], ano: d.getFullYear(), dia_1: iso(d), offset_meses: m });
}
const DATA_HOJE = iso(hoje) + ' (' + DIAS[hoje.getDay()] + ')';

// ---- evento pendente (quando o vendedor responde a uma confirmacao) --------
// Fonte de verdade: leitura fresca ao Airtable (node "Achar Evento Pendente
// (Contexto)"), feita logo no inicio do fluxo. O bilhete devolvido pela app
// (base.evento_pendente) pode vir corrompido (ex.: transcricao_original
// substituida pela resposta atual, tipo "sim"), por isso so serve de reserva
// se a leitura ao Airtable falhar ou nao encontrar o registo.
let EVENTO_PENDENTE = null;
let pendCtx = null;
try { pendCtx = $('Achar Evento Pendente (Contexto)').first().json; } catch (e) {}
const pendRecord = pendCtx && Array.isArray(pendCtx.records) ? pendCtx.records[0] : null;
const pendFields = pendRecord ? (pendRecord.fields || {}) : null;
if (pendFields) {
  let interp = null;
  try { interp = JSON.parse(pendFields.interpretacao || '{}'); } catch (e) { interp = null; }
  if (interp && Array.isArray(interp.eventos) && interp.eventos.length) {
    EVENTO_PENDENTE = {
      dominante: interp.dominante || interp.eventos[0].id || null,
      transcricao_original: pendFields.Transcricao || '',
      eventos: interp.eventos,
    };
  }
}
if (!EVENTO_PENDENTE) {
  const ep = base.evento_pendente;
  if (ep && Array.isArray(ep.eventos) && ep.eventos.length) {
    EVENTO_PENDENTE = {
      dominante: ep.dominante || ep.eventos[0].id || null,
      transcricao_original: ep.transcricao_original || '',
      eventos: ep.eventos,
    };
  }
}

// ---- bloco dinamico --------------------------------------------------------
const dinamico = {
  DATA_HOJE,
  VENDEDOR,
  TRANSCRICAO: trans,
  CANDIDATOS,
  CALENDARIO,
  CALENDARIO_MESES,
  SEQUENCIA_ESTAGIOS,
  ETAPAS_OBRIGATORIAS,
  FLAGS_AUTO,
};
if (MOTIVOS_SAIDA) dinamico.MOTIVOS_SAIDA = MOTIVOS_SAIDA;
if (EVENTO_PENDENTE) dinamico.EVENTO_PENDENTE = EVENTO_PENDENTE;

const mensagem_utilizador =
  Object.entries(dinamico)
    .map(([k, v]) => k + ': ' + (typeof v === 'string' ? v : JSON.stringify(v)))
    .join('\n\n');

return [{
  json: {
    ...base,
    vendedor: VENDEDOR,
    n_candidatos: CANDIDATOS.length,
    dinamico,
    mensagem_utilizador,
  }
}];

// -- ATALHO: confirmacao por botao (sem IA) --------------------------------
// Quando o comercial carrega em "Sim, e isso", nao ha nada para interpretar:
// a interpretacao ja existe e veio dentro do proprio pedido. Este bloco
// devolve a mesma forma que o resto deste ficheiro devolveria, para que
// nenhum no a jusante note a diferenca.
if (!$('Adaptar Resposta (Gemini)').isExecuted) {
  const b = $('Montar Payload').first().json;
  const ep = b.evento_pendente || {};
  const eventos = Array.isArray(ep.eventos) ? ep.eventos : [];
  const meta = ep.meta || {};
  const anc = eventos.map((e) => e && e.ancora).find((a) => a && a.lead_id);
  return [{ json: {
    ...b,
    ref: b.evento_pendente_id || b.ref,
    interpretacao: { eventos, meta, dominante: ep.dominante || null },
    eventos,
    meta,
    precisa_confirmacao: false,
    ancora_ambigua: false,
    lead_id: (anc && anc.lead_id) || null,
    n_eventos: eventos.length,
    pergunta: null,
    opcoes: [],
    sem_accao: eventos.length === 0,
  } }];
}
// -- fim do atalho ---------------------------------------------------------

// PARSE INTERPRETACAO — valida a saida da Secretaria (§6: JSON estrito, nada mais).
const base = $('Montar Payload').first().json;
const resp = $input.first().json || {};

// Resposta da Anthropic Messages API
let bruto = '';
if (Array.isArray(resp.content)) bruto = resp.content.map(b => b.text || '').join('');
else if (typeof resp.completion === 'string') bruto = resp.completion;
else if (typeof resp === 'string') bruto = resp;

if (resp.type === 'error' || resp.error) {
  throw new Error('Secretaria devolveu erro: ' + JSON.stringify(resp.error || resp).slice(0, 300));
}

// Limpar crases/prosa a toda a volta e ficar so com o objecto JSON
let txt = (bruto || '').trim().replace(/^```(?:json)?/i, '').replace(/```$/, '').trim();
const i = txt.indexOf('{'), j = txt.lastIndexOf('}');
if (i < 0 || j <= i) throw new Error('Secretaria nao devolveu JSON. Recebido: ' + txt.slice(0, 200));

let out;
try { out = JSON.parse(txt.slice(i, j + 1)); }
catch (e) { throw new Error('JSON invalido da Secretaria: ' + e.message + ' | ' + txt.slice(0, 200)); }

// Forma minima garantida
const eventos = Array.isArray(out.eventos) ? out.eventos : [];
const meta = Object.assign({
  multiplas_accoes: eventos.length > 1,
  confirmacoes: 0,
  transcricao_incerta: false,
  sem_accao: eventos.length === 0,
  transcricao_invalida_multilead: false,
  leads_detetadas: [],
}, out.meta || {});

// Normalizacoes defensivas (§6: dados e sempre objecto; avisos e sempre array)
for (const [n, ev] of eventos.entries()) {
  if (!ev.id) ev.id = 'e' + (n + 1);
  if (!ev.dados || typeof ev.dados !== 'object') ev.dados = {};
  if (!Array.isArray(ev.avisos)) ev.avisos = [];
  if (!Array.isArray(ev.opcoes_confirmacao)) ev.opcoes_confirmacao = [];
  if (typeof ev.requer_confirmacao !== 'boolean') ev.requer_confirmacao = true;
  if (!ev.ancora || typeof ev.ancora !== 'object') ev.ancora = { estado: 'nao_aplicavel', lead_id: null };
}

// ---- Reforco deterministico da confirmacao (§3.4) --------------------------------
// Nao confiamos so na Secretaria limpar confirmacao_humana ao copiar o evento pendente:
// se a resposta do vendedor bate certo com uma das opcoes_confirmacao do evento que
// estava pendente, fechamos nos a pergunta. Evita ficar preso a repetir sempre o mesmo
// pedido quando a Secretaria devolve o lote copiado mas sem marcar como resolvido.
const epId = base.evento_pendente_id;
const ep = base.evento_pendente;
if (epId && ep && Array.isArray(ep.eventos) && ep.eventos.length) {
  const respostaTexto = String(base.texto || base.resposta || '').trim().toLowerCase();
  const idsPendentes = new Set(ep.eventos.map(e => e.id));
  const eventoDominantePendente = ep.eventos.find(e => e.id === ep.dominante) || ep.eventos[0] || {};
  const opcoesPendentes = eventoDominantePendente.opcoes_confirmacao || [];
  const respostaValida = opcoesPendentes.some(o => String(o.valor || '').trim().toLowerCase() === respostaTexto);
  if (respostaValida) {
    for (const ev of eventos) {
      if (idsPendentes.has(ev.id) && ev.confirmacao_humana) {
        ev.confirmado_por = respostaTexto;
        ev.confirmacao_humana = null;
        ev.requer_confirmacao = false;
      }
    }
  }
}

// Quem faz a pergunta ao comercial e o dominante da agregacao (§6.1)
const perguntas = eventos.filter(e => e.confirmacao_humana);
const dominante = perguntas[0] || null;
const precisa_confirmacao = perguntas.length > 0;
const lead_id = (eventos.find(e => e.ancora && e.ancora.lead_id) || { ancora: {} }).ancora.lead_id || null;
const ancora_ambigua = eventos.some(e => e.ancora && e.ancora.estado === 'ambigua');

return [{
  json: {
    ...base,
    ref: base.evento_pendente_id || base.ref,
    interpretacao: { eventos, meta, dominante: dominante ? dominante.id : null },
    eventos,
    meta,
    n_eventos: eventos.length,
    precisa_confirmacao,
    ancora_ambigua,
    lead_id,
    pergunta: dominante ? dominante.confirmacao_humana : null,
    opcoes: dominante ? dominante.opcoes_confirmacao : [],
    sem_accao: !!meta.sem_accao || eventos.length === 0,
  }
}];

// PREP COMMITTER — monta o bilhete no formato exacto que o Committer consome:
// { _contexto_n8n: { evento_ref, vendedor, resposta_vendedor, lead_id, comercial_id }, eventos: [...], meta: {...} }
const s = $('Parse Interpretação').first().json;

const eventos = Array.isArray(s.eventos) ? s.eventos : [];
if (!eventos.length) throw new Error('Nada para comprometer: array de eventos vazio.');

// lead_id: o primeiro que estiver resolvido no lote
const lead_id = s.lead_id
  || (eventos.find(e => e.ancora && e.ancora.lead_id) || { ancora: {} }).ancora.lead_id
  || null;

// se não há lead_id mas há pelo menos um evento de LEAD NOVA, o Committer
// sabe criar a Lead — não bloquear neste caso.
const temLeadNova = eventos.some(e => e.ancora && e.ancora.estado === 'nova');
if (!lead_id && !temLeadNova) throw new Error('Sem lead_id resolvido — o Committer nao pode escrever sem lead.');

return [{
  json: {
    _contexto_n8n: {
      evento_ref: s.ref,
      vendedor: s.vendedor || null,
      resposta_vendedor: s.resposta || 'sim',
      lead_id,
      comercial_id: s.comercial_id || null,
    },
    eventos,
    meta: s.meta || {},
  }
}];

const raw = $json;
let texto = '';
try { texto = (raw.candidates[0].content.parts || []).map(p => p.text || '').join(''); } catch (e) {}
return [{ json: { content: [ { type: 'text', text: texto } ] } }];

// MONTAR SCHEMA (Gemini) — responseSchema baseline + reescrita dinamica dos enums por agencia (README_GEMINI.md §4).
const schema = JSON.parse("{
  "_comentario": "responseSchema para Gemini (generationConfig.responseSchema + responseMimeType: application/json). Baseline UNIVERSAL — ver README_GEMINI §4: os enums de `estagio_destino` e `motivo` devem ser reescritos em runtime a partir de SEQUENCIA_ESTAGIOS / ETAPAS_OBRIGATORIAS / MOTIVOS_SAIDA da agência, senão a configuração por agência deixa de ter efeito. Remover esta chave antes de enviar.",
  "type": "object",
  "propertyOrdering": ["eventos", "meta"],
  "required": ["eventos", "meta"],
  "properties": {
    "eventos": {
      "type": "array",
      "description": "Ordem fixa (§6): contacto · factos ditos · inferências. Array vazio quando não há acção registável (§4.1).",
      "items": {
        "type": "object",
        "propertyOrdering": [
          "id", "tipo", "categoria", "par", "ancora", "dados",
          "nota_ficheiro", "confirmacao_humana", "opcoes_confirmacao",
          "confirmado_por", "evento_pendente_id", "confianca",
          "requer_confirmacao", "avisos"
        ],
        "required": ["id", "tipo", "categoria", "par", "ancora", "dados", "requer_confirmacao"],
        "properties": {
          "id": { "type": "string", "description": "e1, e2, e3… sequencial dentro deste array." },
          "tipo": {
            "type": "string",
            "enum": ["contacto", "mudanca_estagio", "proposta", "estado_comercial", "lead_nova", "passo_vendedor", "agendamento", "pendencia", "redacao_mensagem", "briefing", "correcao", "banco_proposta"]
          },
          "categoria": {
            "type": "string",
            "description": "Deriva mecanicamente do tipo (tabela §4.0): contacto/mudanca_estagio/proposta/estado_comercial/lead_nova → nota; passo_vendedor/agendamento → evento; pendencia → pendencia; redacao_mensagem/briefing/correcao → outro.",
            "enum": ["evento", "nota", "pendencia", "outro"]
          },
          "par": {
            "type": "string",
            "nullable": true,
            "description": "§10.18. Nos seis tipos que são metade de um facto: o `id` do evento irmão, escrito NO ACTO de gerar este. `ja_la_esta` quando a lead já está nesse estágio ou além. `null` nos restantes tipos. Nunca aponta para um id que não vais escrever."
          },
          "ancora": {
            "type": "object",
            "propertyOrdering": ["n_candidatos", "estado", "lead_id", "nome_exibicao", "telefone", "nome_dito", "resolvida_por", "candidatos"],
            "required": ["n_candidatos", "estado", "lead_id"],
            "properties": {
              "n_candidatos": {
                "type": "integer",
                "description": "P4 — conta ANTES de classificar. Número de candidatos de CANDIDATOS que correspondem ao nome dito. O estado sai deste número, por aritmética."
              },
              "estado": {
                "type": "string",
                "description": "1 candidato → resolvida (com lead_id preenchido). 2+ → ambigua. 0 → nova, ou nao_aplicavel se não houver lead nem acção. O nome ter vindo parcial NÃO entra nesta conta.",
                "enum": ["resolvida", "ambigua", "nova", "nao_aplicavel"]
              },
              "lead_id": { "type": "string", "nullable": true },
              "nome_exibicao": { "type": "string", "nullable": true, "description": "Primeiro e último nome. null se ambigua." },
              "telefone": { "type": "string", "nullable": true },
              "nome_dito": { "type": "string", "nullable": true, "description": "Como foi dito no áudio." },
              "resolvida_por": {
                "type": "string",
                "nullable": true,
                "enum": ["nome", "contexto", "confirmacao", "pendente"]
              },
              "candidatos": {
                "type": "array",
                "description": "Preenchido quando estado = ambigua. Dois ou mais — com um só, o estado é resolvida.",
                "items": {
                  "type": "object",
                  "propertyOrdering": ["id", "nome", "telefone", "fase", "confianca"],
                  "required": ["id", "nome"],
                  "properties": {
                    "id": { "type": "string" },
                    "nome": { "type": "string" },
                    "telefone": { "type": "string", "nullable": true },
                    "fase": { "type": "string", "nullable": true },
                    "confianca": { "type": "number", "nullable": true }
                  }
                }
              }
            }
          },
          "dados": {
            "type": "object",
            "description": "Objecto SEMPRE — um tipo sem campos próprios leva {}, nunca null. Só os campos do tipo em causa. A ordem abaixo é deliberada: os campos que OBRIGAM (prova_de_entrega, derivada_de, fase_origem/motivo/desfecho_proposto) vêm antes dos campos que eles autorizam.",
            "propertyOrdering": [
              "prova_de_entrega", "derivada_de", "fase_origem", "motivo", "motivo_livre",
              "desfecho_proposto", "estagio_destino", "gatilho", "subtipo", "desfecho",
              "depende_de", "descricao", "origem", "data_prometida",
              "tarefa", "prazo", "follow_up_auto", "follow_up_prazo",
              "titulo", "quando", "resumo", "valor", "data_dita",
              "nome", "telefone", "tipo_credito", "origem_lead",
              "alvo", "ancora_errada", "ancora_correta", "pergunta", "banco", "estado_proposta"
            ],
            "properties": {
              "prova_de_entrega": {
                "type": "string",
                "nullable": true,
